import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import {memo} from 'react'

import {useSlice} from '../../../../../hooks/useSlice'
import {EnableAgentPopup} from '../../components/EnableAgentForm/EnableAgentForm'
import styles from '../AgentPage.module.css'

interface Props {
  agent: {
    id?: number | null
    name?: string | null
    enabled?: boolean | null
    cloudInstanceId?: string | null
  }
  className?: string
}

function EnableAgent({agent, className}: Props) {
  const {id, name, enabled = false} = agent
  const [show, actions] = useSlice(
    {
      toggle: prevShow => !prevShow,
      close: (_, __: void) => false,
    },
    false,
  )
  return (
    <div className={classNames(className, styles.enableWrapper)} data-test-enable-agent>
      <Button onClick={actions.toggle}>
        {enabled
          ? agent.cloudInstanceId != null
            ? 'Disable for maintenance...'
            : 'Disable...'
          : 'Enable...'}
      </Button>
      <EnableAgentPopup
        hidden={!show}
        id={id}
        name={name}
        enabled={enabled}
        onClose={actions.close}
      />
    </div>
  )
}

export default memo(EnableAgent)
