import classNames from 'classnames'
import type * as React from 'react'

import Badge from '../../../../../../common/Badge/Badge'

import styles from './AgentHeaderBadge.module.css'

type Props = {
  dataTestId?: string
  className?: string
  isDanger?: boolean
  label?: React.ReactNode
  children?: React.ReactNode
}
function AgentHeaderBadge(props: Props) {
  const {className, isDanger, ...restProps} = props
  return (
    <Badge
      className={classNames(styles.badge, props.className)}
      labelClassName={classNames({[styles.danger]: isDanger})}
      {...restProps}
    />
  )
}

export default AgentHeaderBadge
