import * as React from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import {useAppSelector} from '../../../../hooks/react-redux'
import {useQueryParamState} from '../../../../hooks/routes'
import {usePermission} from '../../../../hooks/usePermission'
import {getBuildLocator} from '../../../../rest/locators'
import {getSingleAgent} from '../../../../selectors'
import type {BuildId} from '../../../../types'
import {stringifyId, Permission} from '../../../../types'
import {useAgentPools} from '../AgentPagePoolsProvider'
import {getAgentTypesHash} from '../AgentsPages.selectors'

import type {AgentPageCanStopBuildQuery} from './__generated__/AgentPageCanStopBuildQuery.graphql'

const canStopBuildQuery = graphql`
  query AgentPageCanStopBuildQuery($buildLocator: String!, $skip: Boolean!) {
    build(buildLocator: $buildLocator) @skip(if: $skip) {
      buildType {
        projectId
      }
    }
  }
`

export const useCanStopBuild = (buildId: BuildId | null | undefined) => {
  const {build} = useLazyLoadQuery<AgentPageCanStopBuildQuery>(canStopBuildQuery, {
    buildLocator: getBuildLocator(buildId),
    skip: buildId == null,
  })
  const {projectId} = build?.buildType ?? {}
  return usePermission(Permission.CANCEL_BUILD, projectId)
}

export function useAgentTypeIdQueryParamEffect(agentId: number) {
  const agent = useAppSelector(state => getSingleAgent(state, agentId))
  const [currentAgentTypeId, setAgentTypeId] = useQueryParamState('agentTypeId')

  const pools = useAgentPools()
  const agentTypes = useAppSelector(state => getAgentTypesHash(state, {pools}))
  const agentType = agent?.typeId != null ? agentTypes[agent.typeId] : null

  React.useEffect(() => {
    const nextAgentTypeId = stringifyId(agent?.typeId)
    if (nextAgentTypeId !== currentAgentTypeId && agentType?.isCloud) {
      setAgentTypeId(stringifyId(agent?.typeId))
    }
  }, [agent?.typeId, agentType?.isCloud, currentAgentTypeId, setAgentTypeId])
}
