import throttle from 'lodash/throttle'
import {useEffect} from 'react'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'
import type {VariablesOf} from 'relay-runtime'

import {useRefetchablePreloadedQuery} from '../../../../../hooks/relay/useRefetchablePreloadedQuery'
import {subscribeOnAgentEvents, subscribeOnOverallEvents} from '../../../../../utils/subscriber'
import {
  AGENT_EVENT_TYPES,
  FREQUENT_OVERALL_AGENT_EVENT_TOPICS,
} from '../../../AgentsPages/AgentsPages.actions'

import type {AgentPipelinePageQuery} from './__generated__/AgentPipelinePageQuery.graphql'
import {query} from './AgentPipelinePage.queries'

const DELAY = 500

export function useAgentSubscription(
  preloadedQuery: PreloadedQuery<AgentPipelinePageQuery>,
): [AgentPipelinePageQuery['response'], (variables: VariablesOf<AgentPipelinePageQuery>) => void] {
  const [data, refetch] = useRefetchablePreloadedQuery(query, preloadedQuery)

  useEffect(() => {
    if (data.agentRest?.id == null) {
      return () => undefined
    }

    const handler = throttle(
      () => {
        refetch({locator: `id:${data.agentRest?.id}`})
      },
      DELAY,
      {leading: true, trailing: true},
    )
    const unsubscribeAgentEvents = subscribeOnAgentEvents(
      data.agentRest?.id,
      AGENT_EVENT_TYPES,
      handler,
    )

    const unsubscribeOverallEvents = subscribeOnOverallEvents(
      FREQUENT_OVERALL_AGENT_EVENT_TOPICS,
      handler,
    )

    return () => {
      unsubscribeAgentEvents()
      unsubscribeOverallEvents()
      handler.cancel()
    }
  }, [data.agentRest?.id, refetch])

  return [data, refetch]
}
