import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {memo} from 'react'
import {useFragment} from 'react-relay'
import {graphql} from 'relay-runtime'

import {displayDate} from '../../../../../../../utils/dateTimeUtils'
import CommentPopup from '../../../../../../common/CommentPopup/CommentPopup'
import CommentIcon from '../../../../../AgentsPages/components/EnableAgentForm/CommentIcon/CommentIcon'
import AgentHeaderBadge from '../Badge/AgentHeaderBadge'

import type {AgentAuthorizedStatus_agentRest$key} from './__generated__/AgentAuthorizedStatus_agentRest.graphql'

import styles from './AgentAuthorizedStatus.module.css'

import {AGENT_AUTHORIZED_AUTOMATICALLY} from 'src/components/pages/AgentsPages/AgentPage/AgentStatus/AgentEnableAuthStatus'
import {useIsAutodetectTimeZone} from 'src/hooks/useIsAutodetectTimeZone'

interface Props {
  agentKey: AgentAuthorizedStatus_agentRest$key | null
}

const fragment = graphql`
  fragment AgentAuthorizedStatus_agentRest on AgentRest {
    authorizedInfo {
      comment {
        text
        timestamp
        user {
          name
          username
        }
      }
      status
    }
  }
`

const directions = [
  Directions.TOP_RIGHT,
  Directions.BOTTOM_RIGHT,
  Directions.TOP_LEFT,
  Directions.BOTTOM_LEFT,
]

function AgentAuthorizedStatus(props: Props) {
  const {agentKey} = props
  const agent = useFragment(fragment, agentKey)
  const isAutodetectTimeZone = useIsAutodetectTimeZone()

  if (agent == null) {
    return null
  }

  const {comment, status} = agent.authorizedInfo ?? {}
  const userName = comment?.user && (comment?.user.name ?? comment?.user.username)

  const authorizedAutomatically = comment?.text === AGENT_AUTHORIZED_AUTOMATICALLY

  const label = status
    ? `Authorized ${authorizedAutomatically ? 'automatically' : ''}`
    : 'Unauthorized'

  return (
    <AgentHeaderBadge dataTestId={'auth-status'} label={label} isDanger={!status}>
      {userName}
      {comment?.timestamp && (
        <span>{` on ${displayDate(comment?.timestamp, isAutodetectTimeZone, true)}`}</span>
      )}
      {comment?.text && comment?.text !== AGENT_AUTHORIZED_AUTOMATICALLY && (
        <CommentPopup
          anchor={<CommentIcon className={styles.comment} />}
          actionTitle={label}
          timestamp={comment?.timestamp}
          user={userName}
          text={comment.text}
          top={-4}
          left={-24}
          directions={directions}
        />
      )}
    </AgentHeaderBadge>
  )
}

export default memo(AgentAuthorizedStatus)
