import {memo} from 'react'
import {graphql, useFragment} from 'react-relay'

import CopyIconButton from '../../../../../../common/CopyIconButton/CopyIconButton'
import AgentAuthorizedStatus from '../AuthorizedStatus/AgentAuthorizedStatus'
import AgentHeaderBadge from '../Badge/AgentHeaderBadge'
import AgentConnectionStatus from '../ConnectionStatus/AgentConnectionStatus'
import AgentEnableStatus from '../EnableStatus/AgentEnableStatus'

import type {AgentHeader_agentRest$key} from './__generated__/AgentHeader_agentRest.graphql'

import styles from './AgentHeader.module.css'

interface Props {
  agentKey: AgentHeader_agentRest$key | null
}

const fragment = graphql`
  fragment AgentHeader_agentRest on AgentRest {
    ...AgentEnableStatus_agentRest
    ...AgentConnectionStatus_agentRest
    ...AgentAuthorizedStatus_agentRest
    port
    ip
    environment {
      osName
    }
  }
`

function AgentHeader(props: Props) {
  const {agentKey} = props
  const agent = useFragment(fragment, agentKey)

  if (agent == null) {
    return null
  }

  return (
    <div data-test={'header'} className={styles.container}>
      <AgentHeaderBadge dataTestId={'id'} label={'IP'}>
        {agent.ip}
        <CopyIconButton
          iconClassName={styles.copy}
          text={agent.ip}
          title={'Copy IP to clipboard'}
        />
      </AgentHeaderBadge>
      <AgentHeaderBadge dataTestId={'os'} label={'OS'}>
        {agent.environment?.osName}
      </AgentHeaderBadge>
      <AgentConnectionStatus agentKey={agent} />
      <AgentAuthorizedStatus agentKey={agent} />
      <AgentEnableStatus agentKey={agent} />
      <AgentHeaderBadge dataTestId={'port'} label={'Port'}>
        {agent.port}
      </AgentHeaderBadge>
    </div>
  )
}
export default memo(AgentHeader)
