import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {Suspense} from 'react'
import {EntryPointContainer, graphql, useFragment} from 'react-relay'
import type {PreloadedEntryPoint} from 'react-relay/relay-hooks/EntryPointTypes'

import {emptyObject} from '../../../../../../utils/empty'
import CopyIconButton from '../../../../../common/CopyIconButton/CopyIconButton'
import Loader from '../../../../../common/Loader/Loader'
import PageTitle from '../../../../../common/PageTitle/PageTitle'
import type {AgentParametersComponentType} from '../../../../AgentsPages/AgentPage/AgentParameters/AgentParameters'
import AgentParametersHelp from '../../components/Help/AgentParametersHelp'
import JobList from '../../JobList/JobList'

import type {AgentPipelinePage_agentRest$key} from './__generated__/AgentPipelinePage_agentRest.graphql'
import AgentPipelineActions from './Actions/AgentPipelineActions'
import AgentHeader from './Header/AgentHeader'

import styles from './AgentPipelinePage.module.css'

import LinuxIcon from 'src/svg/os-linux.svg'
import MacOSIcon from 'src/svg/os-mac.svg'
import WindowsIcon from 'src/svg/os-windows.svg'

interface Props {
  agentKey: AgentPipelinePage_agentRest$key | null
  parametersEntryPoint?: PreloadedEntryPoint<AgentParametersComponentType>
}

const fragment = graphql`
  fragment AgentPipelinePage_agentRest on AgentRest {
    ...AgentHeader_agentRest
    ...AgentPipelineActions_agentRest
    version
    cpuRank
    host
    name
    connected
    enabled
    build {
      id
    }
    environment {
      osName
      osType
    }
  }
`

function getIcon(osType: string | null | undefined) {
  switch (osType) {
    case 'Linux':
      return LinuxIcon
    case 'macOS':
      return MacOSIcon
    case 'Windows':
      return WindowsIcon
    default:
      return 'unknown-os'
  }
}

export default function AgentPipelinePage({agentKey, parametersEntryPoint}: Props) {
  const agent = useFragment(fragment, agentKey)

  if (agent == null) {
    return null
  }

  return (
    <div data-test={'agent-page'} className={styles.page}>
      <div data-test={'title'} className={styles.header}>
        <PageTitle
          className={classNames(styles.title, {
            [styles.disconnectedTitle]: !agent.connected,
            [styles.disabledTitle]: !agent.enabled,
          })}
        >
          <SvgIcon
            className={styles.icon}
            icon={getIcon(agent.environment?.osType)}
            data-test-sidebar-agent={'os-icon'}
          />{' '}
          {agent.name}
        </PageTitle>
        <AgentPipelineActions className={styles.actions} agentKey={agent} />
      </div>
      <AgentHeader agentKey={agent} />
      <div className={styles.summary}>
        <div data-test={'hostname'} className={styles.row}>
          <div className={styles.rowTitle}>{'Hostname'}</div>
          <div>
            {agent.host}
            <CopyIconButton
              text={agent.host}
              iconClassName={styles.copyButton}
              title={'Copy hostname to clipboard'}
            />
          </div>
        </div>
        <div data-test={'cpu'} className={styles.row}>
          <div className={styles.rowTitle}>{'CPU rank'}</div>
          <div>{agent.cpuRank}</div>
        </div>
        <div data-test={'version'} className={styles.row}>
          <div className={styles.rowTitle}>{'Version'}</div>
          <div>{agent.version}</div>
        </div>
        <div data-test={'os-name'} className={styles.row}>
          <div className={styles.rowTitle}>{'Operating system'}</div>
          <div>{agent.environment?.osName}</div>
        </div>
      </div>
      <Suspense>{agent.build?.id && <JobList buildIds={[agent.build.id]} />}</Suspense>
      <H3 className={styles.parametersTitle}>
        {'Agent Parameters'}
        <AgentParametersHelp />
      </H3>
      {parametersEntryPoint && (
        <Suspense fallback={<Loader data-suspense-fallback />}>
          <EntryPointContainer entryPointReference={parametersEntryPoint} props={emptyObject} />
        </Suspense>
      )}
    </div>
  )
}
