import Button from '@jetbrains/ring-ui-built/components/button/button'
import Confirm from '@jetbrains/ring-ui-built/components/confirm/confirm'
import * as React from 'react'

import {restApi} from '../../../../../services/rest'

type Props = {
  className?: string
  agent: {
    id: number
    pool: {
      id?: number
    }
  }
  onRemove: () => void
}

function RemoveAgentButton({className, agent, onRemove}: Props) {
  const [showDeleteConfirm, setShowDeleteConfirm] = React.useState(false)
  const [removeAgent] = restApi.endpoints.deleteAgent.useMutation()
  const onConfirmRemoveAgent = React.useCallback(() => {
    removeAgent({agentLocator: `id:${agent.id}`}).then(result => {
      if (!('error' in result)) {
        onRemove()
      }
    })
    setShowDeleteConfirm(false)
  }, [removeAgent, agent, onRemove])
  const onRejectRemoveAgent = React.useCallback(() => setShowDeleteConfirm(false), [])
  const onClick = React.useCallback(() => setShowDeleteConfirm(true), [])
  return (
    <>
      <Button data-test-remove-agent className={className} onClick={onClick}>
        {'Remove'}
      </Button>
      <Confirm
        text="Remove this agent?"
        confirmLabel="Yes"
        rejectLabel="Cancel"
        show={showDeleteConfirm}
        onConfirm={onConfirmRemoveAgent}
        onReject={onRejectRemoveAgent}
      />
    </>
  )
}

export default React.memo(RemoveAgentButton)
