import classNames from 'classnames'
import * as React from 'react'

import TransformText from '../../../../../containers/TransformText'
import {useDistanceToNow} from '../../../../../hooks/useTimeSelector'
import type {EnabledInfo} from '../../../../../services/rest'
import type {CommentInfo} from '../../../../../types'
import {displayDate} from '../../../../../utils/dateTimeUtils'

import styles from './AgentStatus.module.css'

type Props = {
  enabledInfo: EnabledInfo
  authorizedInfo: EnabledInfo
  isAutodetectTimeZone: boolean
  isCloud: boolean
  className?: string
}
export const AGENT_AUTHORIZED_AUTOMATICALLY = 'Virtual agent is authorized automatically.'

function StatusComment({
  text,
  timestamp,
  user,
  isAutodetectTimeZone,
}: CommentInfo & {
  isAutodetectTimeZone: boolean
}) {
  const userName = (user != null && (user.name != null ? user.name : user.username)) || null
  return (
    <>
      {timestamp != null ? (
        <span>{` on ${displayDate(timestamp, isAutodetectTimeZone, true)}`}</span>
      ) : null}
      {userName != null ? <span>{` by ${userName}`}</span> : null}
      {text != null && text !== AGENT_AUTHORIZED_AUTOMATICALLY ? (
        <>
          <span>{' with comment:'}</span>
          <div className={styles.commentWrapper}>
            <TransformText
              text={`${text}`}
              showLoader={false}
              TagName="span"
              className={styles.comment}
            />
          </div>
        </>
      ) : null}
    </>
  )
}

function SwitchTimeComment({
  switchTime,
  actionTitle,
  isAutodetectTimeZone,
}: {
  switchTime: string
  actionTitle: string
  isAutodetectTimeZone: boolean
}) {
  const switchFromNow = useDistanceToNow(switchTime)
  return (
    <div>
      <span
        className={styles.switchTime}
      >{`Will be ${actionTitle} automatically ${switchFromNow}`}</span>
      <span>{` (${displayDate(switchTime, isAutodetectTimeZone, true)})`}</span>
    </div>
  )
}

function BasicEnableStatus({
  status,
  className,
  isCloud,
}: EnabledInfo & {
  className?: string
  isCloud: boolean
}) {
  return (
    <span className={classNames(status ? styles.statusUp : styles.statusDown, className)}>
      {status ? 'Enabled' : `Disabled${isCloud ? ' for maintenance' : ''}`}
    </span>
  )
}

function BasicAuthorizedStatus({
  status,
  automatically,
  className,
}: EnabledInfo & {
  automatically: boolean
  className?: string
}) {
  return (
    <>
      <span className={classNames(status ? styles.statusUp : styles.statusDown, className)}>
        {status ? 'Authorized' : 'Unauthorized'}
      </span>
      <span>{automatically ? ' automatically ' : ''}</span>
    </>
  )
}

function FullEnableStatus({
  isAutodetectTimeZone,
  isCloud,
  ...enabledInfo
}: EnabledInfo & {
  isAutodetectTimeZone: boolean
  isCloud: boolean
}) {
  return (
    <div className={styles.line} data-agent-enabled-status>
      <BasicEnableStatus {...enabledInfo} isCloud={isCloud} />
      <StatusComment {...enabledInfo.comment} isAutodetectTimeZone={isAutodetectTimeZone} />
      {enabledInfo.statusSwitchTime != null ? (
        <SwitchTimeComment
          switchTime={enabledInfo.statusSwitchTime}
          actionTitle={
            enabledInfo.status ? `disabled${isCloud ? ' for maintenance' : ''}` : 'enabled'
          }
          isAutodetectTimeZone={isAutodetectTimeZone}
        />
      ) : null}
    </div>
  )
}

function FullAuthorizedStatus({
  automatically,
  isAutodetectTimeZone,
  ...authorizedInfo
}: EnabledInfo & {
  isAutodetectTimeZone: boolean
  automatically: boolean
}) {
  return (
    <div className={styles.line} data-agent-authorization-status>
      <BasicAuthorizedStatus {...authorizedInfo} automatically={automatically} />
      <StatusComment {...authorizedInfo.comment} isAutodetectTimeZone={isAutodetectTimeZone} />
      {authorizedInfo.statusSwitchTime != null ? (
        <SwitchTimeComment
          switchTime={authorizedInfo.statusSwitchTime}
          actionTitle={authorizedInfo.status ? 'unauthorized' : 'authorized'}
          isAutodetectTimeZone={isAutodetectTimeZone}
        />
      ) : null}
    </div>
  )
}

function AgentEnableAuthStatus({
  enabledInfo,
  authorizedInfo,
  className,
  isAutodetectTimeZone,
  isCloud,
}: Props) {
  const authorizedAutomatically = authorizedInfo.comment?.text === AGENT_AUTHORIZED_AUTOMATICALLY
  return (
    <div className={className}>
      <FullAuthorizedStatus
        {...authorizedInfo}
        automatically={authorizedAutomatically}
        isAutodetectTimeZone={isAutodetectTimeZone}
      />
      <FullEnableStatus
        {...enabledInfo}
        isAutodetectTimeZone={isAutodetectTimeZone}
        isCloud={isCloud}
      />
    </div>
  )
}

export default React.memo(AgentEnableAuthStatus)
