import {HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import {Suspense} from 'react'
import type {EntryPointProps} from 'react-relay'
import {useParams} from 'react-router'

import useDocumentTitle from '../../../../../hooks/useDocumentTitle'
import {getAgentTypeHref} from '../../../../../routes'
import {toAgentId} from '../../../../../types'
import Loader from '../../../../common/Loader/Loader'
import Redirect from '../../../../common/Redirect/Redirect'
import type {AgentParametersEntryPoint} from '../../../AgentsPages/AgentPage/AgentParameters/AgentParameters.entryPoint'
import {
  useCanViewAgentDetails,
  useSubscribeOnAgentRemoval,
} from '../../../AgentsPages/AgentsPages.hooks'

import type {AgentPipelinePageQuery} from './__generated__/AgentPipelinePageQuery.graphql'
import {useAgentSubscription} from './AgentPipelinePage.hooks'
import AgentPipelinePage from './Page/AgentPipelinePage'

const FORBIDDEN_ERROR = {statusCode: HTTPCodesEnum.FORBIDDEN, message: ''}

type Params = {
  agentId: string
}

type Queries = {main: AgentPipelinePageQuery}
export type EntryPoints = {parameters: typeof AgentParametersEntryPoint}

export default function AgentPipelinePageContainer({
  queries,
  entryPoints,
}: EntryPointProps<Queries, EntryPoints, {}, {}>) {
  const params = useParams<Params>()
  const agentId = toAgentId(params.agentId ?? '')

  const [data] = useAgentSubscription(queries.main)
  useDocumentTitle(data && `Agent Summary (${data.agentRest?.name}) — TeamCity Pipelines`)
  useSubscribeOnAgentRemoval(agentId, true)
  const error = useCanViewAgentDetails(data) ? null : FORBIDDEN_ERROR

  const jbHostedProperty = data.agentRest?.properties?.property?.find(
    property => property.name === 'teamcity.agent.jbHosted',
  )
  const isJetBrainsHosted = jbHostedProperty?.value === 'true'

  if (isJetBrainsHosted) {
    const url = getAgentTypeHref(data.agentRest?.typeId)

    return <Redirect to={url} replace />
  }

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && error != null) {
    throw error
  }

  return (
    <Suspense fallback={<Loader data-suspense-fallback />}>
      <AgentPipelinePage
        agentKey={data.agentRest ?? null}
        parametersEntryPoint={entryPoints.parameters}
      />
    </Suspense>
  )
}
export type AgentPageContainerComponent = typeof AgentPipelinePageContainer
