import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {memo, useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'

import {displayDate} from '../../../../../../../utils/dateTimeUtils'
import Popup from '../../../../../../common/Popup/Popup.lazy'
import CommentIcon from '../../../../../AgentsPages/components/EnableAgentForm/CommentIcon/CommentIcon'
import AgentHeaderBadge from '../Badge/AgentHeaderBadge'

import type {AgentConnectionStatus_agentRest$key} from './__generated__/AgentConnectionStatus_agentRest.graphql'

import styles from './AgentConnectionStatus.module.css'

import {useIsAutodetectTimeZone} from 'src/hooks/useIsAutodetectTimeZone'
import Connected from 'src/svg/connected.svg'

interface Props {
  agentKey: AgentConnectionStatus_agentRest$key | null
}

const fragment = graphql`
  fragment AgentConnectionStatus_agentRest on AgentRest {
    connected
    connectedSince
    disconnectionComment
    lastActivityTime
  }
`

const directions = [
  Directions.TOP_RIGHT,
  Directions.BOTTOM_RIGHT,
  Directions.TOP_LEFT,
  Directions.BOTTOM_LEFT,
]

function AgentConnectionStatus(props: Props) {
  const {agentKey} = props
  const agent = useFragment(fragment, agentKey)

  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const lastActivity = useMemo(
    () =>
      agent?.lastActivityTime && (
        <Dropdown
          anchor={<CommentIcon className={styles.activity} />}
          hoverHideTimeOut={300}
          clickMode={false}
          hoverMode
        >
          <Popup directions={directions}>
            <div className={styles.activityPopup}>
              {`Last communication on ${displayDate(agent.lastActivityTime, isAutodetectTimeZone, true)}`}
            </div>
          </Popup>
        </Dropdown>
      ),
    [agent?.lastActivityTime, isAutodetectTimeZone],
  )

  if (agent == null) {
    return null
  }

  if (agent.connected) {
    return (
      <AgentHeaderBadge dataTestId={'connected'} label={'Connected'}>
        <SvgIcon icon={Connected} title="connected" />
        {agent.connectedSince != null
          ? ` since ${displayDate(agent.connectedSince, isAutodetectTimeZone, true)}`
          : null}
        {lastActivity}
      </AgentHeaderBadge>
    )
  } else {
    return (
      <AgentHeaderBadge isDanger dataTestId={'disconnected'} label={'Disconnected'}>
        <SvgIcon className={styles.disconnectedIcon} icon="disconnected" title="disconnected" />
        {agent.disconnectionComment != null ? ` — ${agent.disconnectionComment}` : ''}
        {lastActivity}
      </AgentHeaderBadge>
    )
  }
}

export default memo(AgentConnectionStatus)
