import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import classNames from 'classnames'
import {memo, Suspense, useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'

import {restApi} from '../../../../../../../services/rest'
import EnableAgent from '../../../../../AgentsPages/AgentPage/EnableAgent/EnableAgent'
import styles from '../AgentPipelinePage.module.css'

import type {AgentPipelineActions_agentRest$key} from './__generated__/AgentPipelineActions_agentRest.graphql'
import AgentPipelineRemoveButton from './AgentPipelineRemoveButton'

import Plugin from 'src/components/common/Plugin/Plugin'

interface Props {
  agentKey: AgentPipelineActions_agentRest$key | null
  className?: string
}

const fragment = graphql`
  fragment AgentPipelineActions_agentRest on AgentRest {
    ...AgentPipelineRemoveButton_agentRest
    id
    connected
    name
    enabled
    cloudInstance {
      id
    }
    build {
      id
    }
    pool {
      id
    }
  }
`

function AgentPipelineActions({agentKey, className}: Props) {
  const agent = useFragment(fragment, agentKey)

  const {isToggleable} = restApi.endpoints.getPoolPermissions.useQuery(undefined, {
    selectFromResult: ({data}) => ({
      isToggleable: agent?.pool?.id != null && data?.[agent?.pool?.id]?.canChangeStatus,
    }),
  })

  const adaptedAgent = useMemo(
    () => ({
      id: agent?.id!,
      name: agent?.name ?? '',
      enabled: agent?.enabled ?? false,
      cloudInstanceId: agent?.cloudInstance?.id!,
      pool: {
        id: agent?.pool?.id!,
      },
    }),
    [agent],
  )

  if (agent == null) {
    return null
  }

  return (
    <div data-test={'agent-actions'} className={className}>
      {isToggleable && (
        <EnableAgent
          agent={adaptedAgent}
          className={classNames(styles.actions, styles.enableAgentButton)}
        />
      )}
      <Suspense>
        <AgentPipelineRemoveButton agentKey={agent} />
      </Suspense>
      <Plugin placeId={PlaceId.SAKURA_AGENT_ACTIONS} inline />
    </div>
  )
}

export default memo(AgentPipelineActions)
