import {memo, useMemo} from 'react'
import {graphql, useFragment} from 'react-relay'
import {useNavigate} from 'react-router'

import useEventCallback from '../../../../../../../hooks/useEventCallback'
import {getAgentsOverviewHref} from '../../../../../../../routes'
import {useCanStopBuild} from '../../../../../AgentsPages/AgentPage/AgentPage.hooks'
import RemoveAgentButton from '../../../../../AgentsPages/AgentPage/RemoveAgentButton/RemoveAgentButton'
import styles from '../AgentPipelinePage.module.css'

import type {AgentPipelineRemoveButton_agentRest$key} from './__generated__/AgentPipelineRemoveButton_agentRest.graphql'

interface Props {
  agentKey: AgentPipelineRemoveButton_agentRest$key | null
  className?: string
}

const fragment = graphql`
  fragment AgentPipelineRemoveButton_agentRest on AgentRest {
    id
    connected
    build {
      id
    }
    pool {
      id
    }
  }
`
function AgentPipelineRemoveButton({agentKey}: Props) {
  const agent = useFragment(fragment, agentKey)

  const canStopBuild = useCanStopBuild(agent?.build?.id)
  const navigate = useNavigate()
  const onRemove = useEventCallback(() => {
    navigate(getAgentsOverviewHref())
  })

  const adaptedAgent = useMemo(
    () => ({
      id: agent?.id!,
      pool: {
        id: agent?.pool?.id!,
      },
    }),
    [agent],
  )

  return agent?.connected || (agent?.build?.id != null && !canStopBuild) ? null : (
    <RemoveAgentButton className={styles.actions} agent={adaptedAgent} onRemove={onRemove} />
  )
}

export default memo(AgentPipelineRemoveButton)
